import {recutCases,recutCase,recutStage,recutMove} from './ribbon-recut-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const units={2:'half',3:'third',4:'quarter',6:'sixth',8:'eighth',12:'twelfth'};
const exampleCaptions=[
 'One of six equal spaces is colored. The flag marks its end.',
 'Split all six spaces. Two of twelve smaller spaces cover the same colored length; the flag stays still.',
 'Join each neighboring pair. One of six larger spaces is colored again.'
];
let visit=null,owner=null;

export function resetRecutSession(){visit=null;owner=null;}
export function recutSession(){return visit?{...visit}:null;}
function current(explorerId){if(owner!==explorerId){resetRecutSession();owner=explorerId;}return visit;}
const button=(attr,label,disabled=false)=>`<button type="button" class="secondary" ${attr}${disabled?' disabled':''}>${label}</button>`;
function ribbonArt({numerator,denominator,stage=0,stages=[denominator],lastAction=null},id){
 const model=recutStage({numerator,denominator,stages},stage),x=45,w=480,end=x+w*model.endpoint/24,y1=46,y2=121,h=30;
 const cuts=model.boundaries.map((p,i)=>{const xx=x+w*p/24,newCut=lastAction==='split'&&stage>0&&(i+1)%2!==0;return `<path data-recut-cut="${newCut?'new':'old'}" d="M${xx} ${y2}v${h}" class="${newCut?'recut-new-cut':'recut-old-cut'}"/>`;}).join('');
 const alt=`One whole from 0 to 1. Uncut reference and ${model.denominator} equal working spaces share the same colored end at ${numerator}/${denominator}. ${model.coloredCount} of ${model.denominator} working spaces are colored. ${lastAction==='split'?'Dashed marks are the new cuts; solid marks are earlier boundaries.':'All visible working boundaries are solid.'}`;
 return `<svg class="recut-diagram" viewBox="0 0 570 190" role="img" aria-label="${esc(alt)}" data-recut-endpoint="${model.endpoint}" data-recut-denominator="${model.denominator}"><defs><pattern id="recut-pattern-${id}" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M-2 2l4-4M0 10L10 0M8 12l4-4" stroke="#8e651c" stroke-width="2"/></pattern></defs><text x="45" y="18">Uncut reference</text><rect x="${x}" y="${y1}" width="${w}" height="${h}" rx="4" class="recut-whole"/><rect x="${x}" y="${y1}" width="${end-x}" height="${h}" class="recut-colored"/><rect x="${x}" y="${y1}" width="${end-x}" height="${h}" fill="url(#recut-pattern-${id})"/><rect x="${x}" y="${y1}" width="${w}" height="${h}" rx="4" class="recut-outline"/><text x="45" y="106">Our equal spaces</text><rect x="${x}" y="${y2}" width="${w}" height="${h}" rx="4" class="recut-whole"/><rect x="${x}" y="${y2}" width="${end-x}" height="${h}" class="recut-colored"/><rect x="${x}" y="${y2}" width="${end-x}" height="${h}" fill="url(#recut-pattern-${id})"/><rect x="${x}" y="${y2}" width="${w}" height="${h}" rx="4" class="recut-outline"/>${cuts}<path d="M${end} 35v45M${end} 114v49" class="recut-endpoint"/><path d="M${end-7} 34l7-10 7 10Z" class="recut-flag"/><text x="45" y="180">0</text><text x="525" y="180" text-anchor="end">1</text></svg>`;
}
function example(visit){const frame=visit.exampleFrame??0,stage=frame===0?0:frame===1?1:0,lastAction=frame===1?'split':frame===2?'join':null;return `<details class="recut-example" id="recut-example"><summary>A smaller worked example</summary><p>This is a different ribbon. It does not change our job.</p>${ribbonArt({numerator:1,denominator:6,stage,stages:[6,12],lastAction},'example')}<p id="recut-example-caption" tabindex="-1">${exampleCaptions[frame]}</p><div class="recut-example-actions">${[0,1,2].map(i=>button(`data-recut-example="${i}" aria-current="${frame===i?'step':'false'}"`,`Picture ${i+1}: ${['1/6','2/12','1/6'][i]}`)).join('')}</div></details>`;}
function board(c,v){
 const m=recutStage(c,v.stage),initial=`${c.numerator}/${c.denominator}`,status=v.lastAction==='split'?`We added a dividing mark in every equal space. The whole and colored end stayed still. Now ${m.coloredCount} of ${m.denominator} smaller equal spaces are colored.`:v.lastAction==='join'?`We joined neighboring pairs by removing the extra dividing marks. The colored end did not move. Now ${m.coloredCount} of ${m.denominator} larger equal spaces are colored.`:'Count spaces, not dividing marks. Try splitting every equal space in two.';
 const narration=`${c.title}. ${c.request} ${status} Current label ${m.coloredCount}/${m.denominator}. Each space is one ${units[m.denominator]} of this whole. The colored length is still ${initial} of the same whole.`;
 return `<h2 id="recut-board-title" tabindex="-1">${esc(c.title)} · ${m.coloredCount}/${m.denominator}</h2><p class="recut-request">${esc(c.request)}</p><figure class="recut-figure"><figcaption><strong>One whole from 0 to 1.</strong> Uncut reference: the same colored length. Our ribbon with equal spaces. Colored end stays here.</figcaption>${ribbonArt({...c,...v},'live')}<p class="recut-picture-text">${m.coloredCount} of ${m.denominator} equal spaces are colored. The flag stays at ${initial} of the same whole. ${v.lastAction==='split'?'Solid marks show older boundaries; dashed marks show only the new cuts.':v.lastAction==='join'?'Only the surviving larger-space boundaries remain.':'Solid marks show the starting boundaries.'}</p></figure><div class="recut-actions">${button('data-recut-move="split"','Split every equal space in two',v.stage===c.stages.length-1)}${button('data-recut-move="join"','Join neighboring pairs',v.stage===0)}</div><p class="recut-status" id="recut-status" role="status" tabindex="-1">${status}</p><p>Each space is one ${units[m.denominator]} of this whole. The colored length is still ${initial} of the same whole.</p><p><strong>Current fraction:</strong> ${m.coloredCount}/${m.denominator}.</p>${hearButton(narration,'Hear this picture')}<details id="recut-help"><summary>How can both numbers change?</summary><p>Each old equal space becomes two smaller equal spaces. The whole has twice as many spaces, and the same colored stretch covers twice as many spaces. Joining neighboring pairs reverses that cut. The colored length never moved.</p></details><details><summary>Talk together</summary><p>Which old boundaries stayed? Which new cuts appeared? After joining pairs, where is the colored end?</p></details>${example(v)}<details class="recut-choose"><summary>Choose another ribbon job</summary><p>Choosing another job starts its first picture. This screen visit is not saved.</p>${catalog()}</details>`;
}
function catalog(){return `<div class="recut-catalog">${recutCases.map(c=>button(`data-recut-start="${c.id}"`,c.title)).join('')}</div>`;}
export function recutPage(explorerId){
 const v=current(explorerId),c=recutCase(v?.caseId);
 return `<div class="recut-page"><header class="page-heading"><a class="back" href="#workshop">← Workshop</a><a class="back" href="#workshop/fractions">Same Amount, New Cuts</a><a class="back" href="#cafe/fractions">Fraction Trail</a><h1>Ribbon Recut Table</h1><p>One whole ribbon. The colored end stays at the brass flag while we change the dividing marks.</p></header><section class="recut-sheet">${c?board(c,v):`<h2 id="recut-chooser-title" tabindex="-1">Choose a ribbon job</h2><p>Each case is open. Choosing a different job starts a fresh screen visit; nothing here is saved.</p>${catalog()}`}<p>At this table, we change the size of the fractional units while the colored amount stays fixed. At Join the Portions, same-size fractional pieces move together and the tray holds more.</p><a class="back" data-common-link href="#workshop/common-cuts">Give two ribbons common cuts</a><a class="back" href="#cafe/portions">Join portions with the same-size pieces</a><p class="recut-model-note">A made-up screen ribbon, not a measured cloth length. The labels and picture show these five cases; they do not prove a rule for every fraction.</p><details><summary>For grown-ups</summary><p>Optional help, local speech, and button use establish no independent reasoning or attainment. The displayed fractions are supplied model labels.</p></details></section></div>`;
}
export function bindRecut({render,focus,explorerId}){
 const root=document.querySelector('.recut-page');if(!root)return;
 const capturedOwner=explorerId(),capturedVisit=current(capturedOwner);
 const live=()=>root.isConnected&&location.hash==='#workshop/recut'&&explorerId()===capturedOwner&&owner===capturedOwner&&visit===capturedVisit;
 const redraw=(selector,keepExample=false)=>{render();if(keepExample){const d=document.querySelector('#recut-example');if(d)d.open=true;}focus(selector);};
 root.querySelectorAll('[data-recut-start]').forEach(b=>b.addEventListener('click',()=>{if(!live()||!recutCase(b.dataset.recutStart))return;visit={caseId:b.dataset.recutStart,stage:0,lastAction:null,exampleFrame:0};redraw('#recut-board-title');}));
 root.querySelectorAll('[data-recut-move]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const next=recutMove(visit,b.dataset.recutMove);if(!next)return;visit={...next,exampleFrame:0};const reverse=b.dataset.recutMove==='split'?'join':'split';redraw(next.stage===0||next.stage===recutCase(next.caseId).stages.length-1?`[data-recut-move="${reverse}"]`:`[data-recut-move="${b.dataset.recutMove}"]`);}));
 root.querySelectorAll('[data-recut-example]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;visit={...visit,exampleFrame:Number(b.dataset.recutExample)};redraw(`[data-recut-example="${visit.exampleFrame}"]`,true);}));
 root.querySelector('#recut-example')?.addEventListener('toggle',e=>{if(!e.target.open&&live()&&visit.exampleFrame!==0){visit={...visit,exampleFrame:0};redraw('#recut-example > summary');}});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
}
